-- ============================================================================
-- seed_etl_run_config_TRS.sql  (TRS step-driver refactor)
--
-- Seeds COMMON.ETL_RUN_CONFIG_TBL for workflows wf_TRS_Stage_Load_1_Ongoing
-- and wf_TRS_Stage_Load_TOA: one row per driver row (STEP_NO = 0,
-- IS_DRIVER = 'Y') + every transform step + every publish branch (+ the
-- PTYDEACT checkpoint-only step 50). All IS_RUN_ENABLED = 'Y'
-- (everything runs). The DELETE below removes TRS rows only (both
-- workflows), so re-running this seed is safe. Run it in the COMMON
-- schema (MDM_ETL_COMMON.COMMON).
-- NOTE: IS_DEPENDENT / DEPENDENT_ON / WORK_TABLES_PRODUCED are
-- informational for a driver run -- gating is by IS_RUN_ENABLED only.
-- The operator ONLY toggles IS_RUN_ENABLED; the driver does NOT
-- validate flag consistency.
-- ============================================================================

DELETE FROM ETL_RUN_CONFIG_TBL WHERE WORKFLOW_NAME IN ('wf_TRS_Stage_Load_1_Ongoing', 'wf_TRS_Stage_Load_TOA');


-- 119 rows: 15 driver rows + 104 steps/branches (including the PTYDEACT checkpoint-only step 50).
